import Foundation

/// The logo of each agent as a PNG in white and in black, since a row draws its icon as it is, with no tint.
enum Logo {
    static let png = [
        "white/claude": "",
        "white/openai": "",
        "black/claude": "",
        "black/openai": "",
    ]

    /// Writes each logo into a folder once, and gives the folder of the colour that reads on the appearance of macOS.
    static func files(in folder: URL, dark: Bool) -> URL {
        for (name, text) in png {
            let file = folder.appendingPathComponent("\(name).png")
            guard !FileManager.default.fileExists(atPath: file.path), let data = Data(base64Encoded: text) else { continue }
            try? FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
            try? data.write(to: file)
        }
        return folder.appendingPathComponent(dark ? "white" : "black")
    }
}
